import type { SoilTestRequest } from "../redux";

/**
 * PDF is generated by the backend (multi-vendor-api) and streamed back.
 * Base URL comes from VITE_API_BASE_URL.
 */
const API_BASE_URL = (
  (import.meta as any).env?.VITE_API_BASE_URL || "http://localhost:3000/api/v1"
).replace(/\/+$/, "");

function extractFilename(header: string | null, fallback: string): string {
  if (!header) return fallback;
  const match = /filename\*?=(?:UTF-8'')?"?([^";]+)"?/i.exec(header);
  return match ? decodeURIComponent(match[1]) : fallback;
}

export async function generateSoilReportPdf(request: SoilTestRequest): Promise<void> {
  const id = encodeURIComponent(request.id);
  const res = await fetch(`${API_BASE_URL}/soil-tests/${id}/report-pdf`, {
    method: "GET",
    headers: { Accept: "application/pdf" },
  });

  if (!res.ok) {
    let message = "Failed to download PDF";
    try {
      const body = await res.json();
      message = body?.message || message;
    } catch {
      /* ignore */
    }
    alert(message);
    throw new Error(message);
  }

  const blob = await res.blob();
  const filename = extractFilename(
    res.headers.get("Content-Disposition"),
    `KrishiKunjo_Soil_Test_Report_${request.id}.pdf`
  );

  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
